import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  // --- Quote: processing fee and empty policy ---
  it.todo("quotes an empty item list as premium 5 G (processing fee only)");

  // --- Quote: base premiums per main item type (parallel price-list catalogue) ---
  it.todo("quotes a plain sword as premium 105 G (100 G base + 5 G fee)");
  it.todo("quotes a plain amulet as premium 65 G (60 G base + 5 G fee)");
  it.todo("quotes a plain staff as premium 85 G (80 G base + 5 G fee)");
  it.todo("quotes a plain potion as premium 45 G (40 G base + 5 G fee)");

  // --- Quote: component base premiums (parallel component catalogue) ---
  it.todo("quotes a single rune as premium 30 G (25 G base + 5 G fee)");
  it.todo("quotes a single moonstone as premium 30 G (25 G base + 5 G fee)");

  // --- Quote: building block of 3 alike components ---
  it.todo("quotes 2 runes as base premium 50 G (no block)");
  it.todo("quotes 3 runes as base premium 60 G (block applies)");
  it.todo("quotes 4 runes as base premium 100 G (no block -- block requires exactly 3)");
  it.todo("quotes 7 runes as base premium 175 G (no block at 7)");
  it.todo("quotes 2 runes + 1 moonstone as base premium 75 G (no block: alike means same type)");
  it.todo("quotes 3 runes + 3 moonstones as base premium 120 G (two separate blocks)");

  // --- Quote: item-specific modifiers ---
  it.todo("adds a 50 % curse surcharge to the cursed item's base premium (cursed sword, 0 years, premium 165 G)");
  it.todo("adds a 30 % high-enchantment surcharge at enchantment exactly 5 (sword enchantment 5)");
  it.todo("adds no high-enchantment surcharge at enchantment 4 (sword enchantment 4)");
  it.todo("adds both curse and high-enchantment surcharges to a cursed sword with enchantment 5");
  it.todo("applies item-specific surcharges only to the affected item: cursed sword + plain amulet -> 210 G before policy modifiers and fee");

  // --- Quote: policy-wide modifiers ---
  it.todo("applies a 20 % loyalty discount on the policy base premium at exactly 2 years with MHPCO");
  it.todo("applies no loyalty discount at 1 year with MHPCO");
  it.todo("applies a 10 % first-insurance surcharge on the policy base premium for every quote");
  it.todo("applies a 15 % follow-up discount on the policy base premium for each contract after the first quote");
  it.todo("applies no follow-up discount to the customer's first quote");

  // --- Quote: rounding in the MHPCO's favour ---
  it.todo("rounds a premium of 197.5 G up to 198 G (MHPCO's favour)");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");

  // --- Quote: integration examples ---
  it.todo("quotes a newcomer's cursed sword (0 years, first contract, enchantment 3) as premium 165 G");
  it.todo("quotes a long-standing customer's second contract (3 years, cursed sword, enchantment 7) as premium 160 G");

  // --- Quote: rejection ---
  it.todo("rejects a quote containing an unknown item type (e.g. broomstick): CLI exits non-zero, error on stderr, no results on stdout");

  // --- Claim: insurance sum and cap ---
  it.todo("caps a single-sword policy at 2000 G (2 x insurance sum 1000 G)");
  it.todo("sums insurance values across items: sword + amulet -> insurance sum 1600 G, cap 3200 G");
  it.todo("bases the cap on unmodified insurance values: cursed sword (premium 165 G) -> cap 2000 G");
  it.todo("excludes the block discount from the insurance sum: sword + 3 runes -> insurance sum 1750 G, cap 3500 G");
  it.todo("sums two swords to insurance sum 2000 G, cap 4000 G");

  // --- Claim: standard reimbursement and deductible ---
  it.todo("pays out 400 G for a steel sword (enchantment 3) with 500 G damage (full minus 100 G deductible)");
  it.todo("pays out 100 G for a rune with 200 G damage (no enchantment or material, so no special clause)");
  it.todo("applies the 100 G deductible once per damaged item: sword 500 G + amulet 300 G -> payout 600 G");
  it.todo("treats two damage entries of the same item type as separate damages with their own deductible (two swords)");

  // --- Claim: special clauses ---
  it.todo("reimburses damage to an item with enchantment exactly 8 at 50 %: dragon sword, 1000 G damage -> payout 400 G");
  it.todo("fully reimburses dragon-material damage: dragon sword enchantment 5, 800 G damage -> payout 700 G");
  it.todo("lets the 50 % high-enchantment clause win over dragon material: dragon sword enchantment 9, 1000 G damage -> payout 400 G");
  it.todo("applies only the high-enchantment clause to a steel sword enchantment 9, 1000 G damage -> payout 400 G");

  // --- Claim: cap exhaustion across successive claims ---
  it.todo("pays out 1400 G on a first 1500 G claim against a 1000 G sword policy, leaving cap 600 G");
  it.todo("reduces a second 1500 G claim to the remaining cap: payout 600 G, remainingCap 0 G");

  // --- Claim: rounding in the MHPCO's favour ---
  it.todo("rounds a payout of 350.5 G down to 350 G (MHPCO's favour)");

  // --- Claim: rejections ---
  it.todo("rejects a claim whose damaged item is not part of the policy (amulet damaged, only a sword insured): CLI exits non-zero, error on stderr");
  it.todo("rejects a claim referencing an unknown item type: CLI exits non-zero, error on stderr");
  it.todo("rejects a claim with more damage entries of a type than the policy covers (two sword damages, one sword insured): CLI exits non-zero, error on stderr");
  it.todo("rejects a claim containing a damage entry with a negative amount (-200): CLI exits non-zero, error on stderr");

  // --- CLI: end-to-end scenario processing ---
  it.todo("reads a scenario from stdin and writes one result per step in order (schema example: quote then claim)");
  it.todo("processes steps sequentially so a claim refers to the policy created by the quote step at its zero-based index");
});

