input.command:
cat > src/claim-office.ts <<'EOF'
export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

const PROCESSING_FEE = 5;
const COMPONENT_BASE_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;
const CURSE_SURCHARGE_RATE = 0.5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: COMPONENT_BASE_PREMIUM,
  moonstone: COMPONENT_BASE_PREMIUM,
};

function countAlikeItems(items: Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
}

function basePremiumForAlikeItems(type: string, count: number): number {
  if (count === BLOCK_SIZE) {
    return BLOCK_BASE_PREMIUM;
  }
  return count * BASE_PREMIUMS[type];
}

function policyBasePremium(items: Item[]): number {
  let total = 0;
  for (const [type, count] of countAlikeItems(items)) {
    total += basePremiumForAlikeItems(type, count);
  }
  return total;
}

function itemRiskSurcharges(items: Item[]): number {
  return items.reduce(
    (total, item) =>
      total + (item.cursed === true ? BASE_PREMIUMS[item.type] * CURSE_SURCHARGE_RATE : 0),
    0,
  );
}

export function quote(
  _customer: Customer,
  items: Item[],
  _previousQuoteCount: number,
): number {
  const basePremium = policyBasePremium(items);
  const premium =
    basePremium +
    itemRiskSurcharges(items) +
    basePremium * FIRST_INSURANCE_SURCHARGE_RATE +
    PROCESSING_FEE;
  return Math.ceil(premium);
}
EOF
